"""Display setup request contracts and five-pool world reset."""
import hashlib,json
from pathlib import Path
from inventory_rom import ROM_HASH
from m68k_static import Decoder
p=Path(__file__).resolve().parents[1];root=p.parents[1];rom=(p/'local/rolo.md').read_bytes();assert hashlib.sha256(rom).hexdigest()==ROM_HASH
rp=root/'work/display-resource-reset-results.json';r=json.loads(rp.read_text(encoding='utf-8-sig'));assert r==dict(passed=True,**{'2694':65543,'setup':256,'2816':256,'27DA':256})
sources=['src/core/display_setup.hpp','src/core/world_resource_reset.hpp','src/core/plane_scroll.hpp','src/core/actor_allocation.hpp','src/core/player_trigger_pool.hpp','src/core/actor_markers.hpp','src/core/actor_reservations.hpp','tests/display_resource_reset_verification_tests.cpp'];exe=root/'work/display_resource_reset_verification_tests.exe';assert exe.stat().st_mtime>=max((p/s).stat().st_mtime for s in sources)
inv=json.loads((p/'docs/stage9/inventory.json').read_text(encoding='utf-8'));accepted={a for x in inv['routines'] for a in x['blocks']};records=[]
specs=[(0x2674,0x2684,'Reset pattern queue: clear exactly firstLONG and publish cursorFFFFEB56; retain remaining queue bytes.'),(0x2684,0x2694,'Reset secondary queue: clear exactly firstLONG and publish cursorFFFFE448; retain remaining queue bytes.'),(0x2816,0x2838,'32 freeLONG record keys FFFF64AE+34*i then terminalnull; cursor resets to first native slot, all34byte payloads retained.'),(0x27da,0x27f0,'Five original reset calls in order: actor free stack27F0, small record2816, trigger2838, deferred2860, reservation2888. Existing actor reset changes only byte0; other payloads stale.'),(0x2694,0x26bc,'Publish name increment2, command=((destinationlow&3FFF)<<16)|((destinationlow>>14)&3)|control. CountWORDpredecrement signednegative skips data, including0 and8001..FFFF; otherwise emits count identical WORDs.'),(0x684e,0x6864,'Request26BC bytefill destinationC000, value0, control40000080, count1000.'),(0x6864,0x687a,'Request26BC bytefill destinationE000, value0, control40000080, count1000.'),(0x687a,0x6894,'Call2694 with wordE000, destinationD000, count0700, control40000000: increment/command then1792 identical words.'),(0x6894,0x68ae,'Call2694 with wordE000, destinationD000, count0, control40000000: increment/command still published, no data words.'),(0x68ae,0x68d2,'Clear exactly eight SAT bytes then request2466 sourceFFFFC9BC,destinationF400,control40000080,4words. Rest of SAT retained.'),(0x31b8,0x31d6,'Request2468 source27040,destinationF680,0480words,control40000000.'),(0x2fe8,0x2ff6,'Forward incoming source/destination to2468 with15words andcontrolC0000000.'),(0x6ac6,0x6aee,'Clear modeF286, foreground/backgroundX, call6960; only then clear bothY and call6960 again. No vertical6AA6 call.')]
for start,end,contract in specs:
 at=start;items=[]
 while at<end:
  assert at in accepted;i=Decoder(rom,at).decode();items.append(i);at+=i['size']
 assert at==end
 records.append(dict(address=start,hex=f'{start:06X}',end_exclusive=end,original_bytes=rom[start:end].hex(),instruction_evidence=items,verification_status='verified',status='verified green: local display/resource setup',native_sources=sources[:2],checked_cases=r[f'{start:04X}'] if f'{start:04X}' in r else r['setup'],contract=contract,proof='Independent full byte/pool and named request/event comparisons. All65536WORD destination/value patterns for2694 with counts0..7 plus signed-count boundaries0/1/2/7FFF/8000/8001/FFFF. Remaining counts follow identical fixed-word repetition, no data-dependent branch.256 priorBYTE patterns for queue/SAT/reset guards; five pools compare keys/cursors/heads and all retained payload bytes. Scroll spy observes original Y values at first horizontal call and zeroY at second, asserting no vertical call. Original constants and full instruction boundaries pinned.',scope='Local typed state and exact native graphics request contracts. For tail26BC/2466/2468 calls, named payload/service handoff is the declared domain; DMA execution/VDP timing/capacity/caller ABI remains external.2694 has complete typed command/data publication loop, not a VDP emulator. Reset pools are distinct valid native objects. New utilities await caller binding where existing host services are partial; no added playable scene claim.'))
report=dict(rom_sha256=ROM_HASH,source_sha256={s:hashlib.sha256((p/s).read_bytes()).hexdigest() for s in sources},records=records,test_executable_sha256=hashlib.sha256(exe.read_bytes()).hexdigest(),results_sha256=hashlib.sha256(rp.read_bytes()).hexdigest())
(p/'docs/stage9/display-resource-reset-verification.json').write_text(json.dumps(report,indent=2)+'\n',encoding='utf-8');print('Thirteen display/resource setup contracts verified.')
